#!/bin/bash
# Bundle channel JS into a Swift source file
DIST_DIR="$(dirname "$0")/../../dist"
OUT="$(dirname "$0")/ChannelExampleApp/BundledChannel.swift"

BRIDGE=$(cat "$DIST_DIR/native-bridge.js")
CHANNEL=$(cat "$DIST_DIR/channel.js")

# Escape backslashes, then escape for Swift multiline string (only # needed for raw strings)
cat > "$OUT" << 'HEADER'
// Auto-generated by bundle-channel-swift.sh — do not edit
import Foundation

HEADER

echo 'let bundledNativeBridgeJS: String = ###"""' >> "$OUT"
cat "$DIST_DIR/native-bridge.js" >> "$OUT"
echo '"""###' >> "$OUT"
echo '' >> "$OUT"
echo 'let bundledChannelJS: String = ###"""' >> "$OUT"
cat "$DIST_DIR/channel.js" >> "$OUT"
echo '"""###' >> "$OUT"

BRIDGE_SIZE=$(wc -c < "$DIST_DIR/native-bridge.js" | tr -d ' ')
CHANNEL_SIZE=$(wc -c < "$DIST_DIR/channel.js" | tr -d ' ')
echo "Bundled ${BRIDGE_SIZE}B bridge + ${CHANNEL_SIZE}B channel → $OUT"
